async function upstream(url){const r=await fetch(url,{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('Operator returned '+r.status);return r;}
function options(html){return [...html.matchAll(/<option value="(\d+)">([^<]+)<\/option>/g)].map(m=>({id:m[1],label:m[2]}));}
function coords(html,list){for(const m of html.matchAll(/new Exit\('[^']*', 0, 0, '[^']*', (\d+), ([\d.-]+), ([\d.-]+)/g)){const p=list.find(p=>p.id===m[1]);if(p){p.latitude=+m[2];p.longitude=+m[3];}}return list;}

